scenarios.example_code:
import { claimTask } from '@projexlight/sdk-assignment';
const { assignment_id, lease_expires_at } = await claimTask({
  tenant_id, persona_id, territory_id,
  preferred_skill: 'hvac-residential',
});

// driven by the background sweeper:
startLeaseSweeper({ tenant_id, interval_ms: 60_000 });
// At each tick: SELECT * FROM assignment WHERE status='claimed' AND lease_expires_at < now();
// → releaseAssignment for each.

import { reassignTask } from '@projexlight/sdk-assignment';
await reassignTask({
  assignment_id, new_persona_id,
  reason: 'requires senior diagnostic skills',
  supervisor_persona_id,
});

import { rebalanceTerritory } from '@projexlight/sdk-assignment';
const { moves } = await rebalanceTerritory({
  tenant_id, territory_id,
  variance_threshold: 0.30, // max 30% spread
});

// driven by event subscription:
subscribeEvents('dispatch.task.cancelled.v1', async (e) => {
  await releaseAssignmentByTask({ task_id: e.payload.task_id, reason: 'customer-cancelled' });
});
